import{$,download,copy,status}from'./common.js';
let colors=['#f4ead8','#243c3b','#de8765','#7a9b84','#c5b7d0'],locks=[false,false,false,false,false];const sets=[['#e8e8df','#2f4550','#b8c5b0','#d59567','#827194'],['#f9f0e1','#583e55','#be8b78','#dfba8e','#93a8a2'],['#e6eafb','#253660','#847cce','#5eb4b0','#efb969'],['#e8eee6','#264d42','#80a68c','#d1b277','#9d7b72']];
function render(){const host=$('#swatches');host.replaceChildren();colors.forEach((color,i)=>{const el=document.createElement('article');el.className='swatch';el.innerHTML=`<div class="color" style="background:${color}"><input aria-label="Choose color ${i+1}" type="color" value="${color}"></div><div class="meta"><button class="hex" aria-label="Copy ${color}">${color.toUpperCase()}</button><button class="lock" aria-label="${locks[i]?'Unlock':'Lock'} color ${i+1}" aria-pressed="${locks[i]}">${locks[i]?'●':'○'}</button></div>`;el.querySelector('input').oninput=e=>{colors[i]=e.target.value;render()};el.querySelector('.hex').onclick=()=>copy(colors[i]);el.querySelector('.lock').onclick=()=>{locks[i]=!locks[i];render()};host.append(el)});const card=$('#uiPreview');card.style.background=colors[0];card.style.color=colors[1];card.querySelector('.eyebrow').style.color=colors[1];$('#previewAction').style.background=colors[2];$('#previewAction').style.color=luminance(colors[2])>.35?'#182129':'#ffffff'}
function luminance(hex){const rgb=hex.match(/\w\w/g).map(n=>parseInt(n,16)/255).map(n=>n<=.04045?n/12.92:((n+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722}
function contrast(){const fg=$('#foreground').value,bg=$('#background').value,l=[luminance(fg),luminance(bg)].sort((a,b)=>b-a),ratio=(l[0]+.05)/(l[1]+.05);$('#contrast').textContent=ratio.toFixed(2)+':1';$('#rating').textContent=ratio>=7?'AAA pass':ratio>=4.5?'AA pass':'Below AA';$('#contrastPreview').style.background=bg;$('#contrastPreview').style.color=fg}
$('#shuffle').onclick=()=>{const set=sets[Math.floor(Math.random()*sets.length)];colors=colors.map((c,i)=>locks[i]?c:set[i]);render();status('Palette shuffled. Locked colors were kept.')};$('#export').onclick=()=>{download(new Blob([':root {\n'+colors.map((c,i)=>`  --color-${i+1}: ${c};`).join('\n')+'\n}\n'],{type:'text/css'}),'palette.css');status('CSS palette downloaded.')};$('#foreground').oninput=$('#background').oninput=contrast;$('#previewAction').onclick=()=>{status('This preview uses your palette. Copy the colors or export CSS to use them.')};$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const image=await createImageBitmap(file);const c=document.createElement('canvas');c.width=c.height=80;const g=c.getContext('2d');g.drawImage(image,0,0,80,80);image.close();const data=g.getImageData(0,0,80,80).data,bins=new Map();for(let i=0;i<data.length;i+=4){if(data[i+3]<128)continue;const values=[data[i],data[i+1],data[i+2]],key=values.map(n=>Math.floor(n/32)).join(',');const b=bins.get(key)||{count:0,sum:[0,0,0]};b.count++;values.forEach((n,k)=>b.sum[k]+=n);bins.set(key,b)}const top=[...bins.values()].sort((a,b)=>b.count-a.count);const chosen=[];for(const b of top){const rgb=b.sum.map(n=>Math.round(n/b.count));if(chosen.every(v=>Math.hypot(...rgb.map((n,k)=>n-v[k]))>55))chosen.push(rgb);if(chosen.length===5)break}if(!chosen.length)throw Error('No visible colors found in this image.');while(chosen.length<5)chosen.push(chosen[chosen.length-1]);colors=colors.map((c,i)=>locks[i]?c:'#'+chosen[i].map(n=>n.toString(16).padStart(2,'0')).join(''));render();status('Palette extracted. Locked colors were kept.')}catch(e){status(e.message||'Could not read this image.',true)}};render();contrast();
